402	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
403	            @RequestBody Retirement request) {
404	        return PersonView.of(people.retire(sheetId, user, id, request.from()), people.today(sheetId));
405	    }
406	
407	    /** Give the person an alias. */
408	    @PostMapping("/{id}/aliases")
409	    public PersonView addAlias(
410	            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
411	            @PathVariable long id,
