437	package net.officefloor.hq.app.person;
438	
439	import java.time.LocalDate;
440	import java.util.List;
441	import java.util.Locale;
442	import java.util.Objects;
443	import net.officefloor.hq.app.Audit;
444	import net.officefloor.hq.app.rollup.Rollup;
445	import net.officefloor.hq.app.sheet.SheetService;
446	import org.springframework.dao.DataIntegrityViolationException;
447	import org.springframework.http.HttpStatus;
448	import org.springframework.orm.ObjectOptimisticLockingFailureException;
449	import org.springframework.stereotype.Service;
450	import org.springframework.transaction.annotation.Transactional;
451	import org.springframework.web.server.ResponseStatusException;
452	
453	/** The people kept on a sheet. */
454	@Service
455	public class PersonService {
456	
457	    private final PersonRepository people;
458	    private final SheetService sheets;
459	    private final Audit audit;
460	    private final Rollup rollup;
461	
462	    public PersonService(PersonRepository people, SheetService sheets, Audit audit, Rollup rollup) {
463	        this.people = people;
464	        this.sheets = sheets;
465	        this.audit = audit;
466	        this.rollup = rollup;
467	    }
468	
469	    /** Everyone on the sheet, in the order they were added. */
470	    @Transactional(readOnly = true)
471	    public List<Person> list(String sheetId) {
472	        return people.findBySheetIdOrderByIdAsc(sheetId);
473	    }
474	
475	    /** Add a person on no terms of their own. */
476	    @Transactional
477	    public Person add(String sheetId, String user, String name, String grade) {
478	        return add(sheetId, user, name, grade, null);
479	    }
480	
481	    /** Add a person with their own terms (null: none); the name is stored trimmed and must not already be in use
482	     *  on the sheet. */
483	    @Transactional
484	    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
485	        return add(sheetId, user, name, grade, terms, null);
486	    }
487	
488	    /** Add a person with their own terms (null: none) and contact (stored trimmed and lower-cased; blank or null:
489	     *  none); the name and the contact must not already be in use on the sheet. */
490	    @Transactional
491	    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
492	        sheets.load(sheetId, user);
493	        String trimmed = name.trim();
494	        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)
495	                || people.findBySheetIdAndAliasIgnoreCase(sheetId, trimmed).isPresent()) {
496	            throw nameInUse();
497	        }
498	        String reach = contactOf(contact);
499	        if (reach != null && people.existsBySheetIdAndContact(sheetId, reach)) {
500	            throw contactInUse();
501	        }
502	        Rollup.Figures before = rollup.of(sheetId);
503	        Person person = new Person(sheetId, trimmed, grade);
504	        person.setTerms(terms);
505	        person.setContact(reach);
506	        Person added = save(person);
507	        audit.recordChangeOnCommit(sheetId, user, entry("PERSON_ADDED", user, added, grade)
508	                + (terms != null ? " terms=" + terms : "") + (reach != null ? " contact=" + reach : ""));
509	        rollup.recordChanges(sheetId, user, before);
510	        return added;
511	    }
512	
513	    /** The sheet's today, or null for a sheet never loaded. */
514	    @Transactional(readOnly = true)
515	    public LocalDate today(String sheetId) {
516	        return sheets.today(sheetId);
517	    }
518	
519	    /**
520	     * Edit a person, as loaded at {@code version}: refused when someone has saved them since. The grade is
521	     * recorded from {@code gradeFrom} (null: the sheet's today), keeping the grades already recorded from
522	     * other dates; a save leaving the grade as in force on the sheet's today, with no from-date, records none.
523	     * The person's own terms become {@code terms} (null: none); their contact is kept.
524	     */
525	    @Transactional
526	    public Person update(String sheetId, String user, long id, long version, String name, String grade,
527	            LocalDate gradeFrom, Integer terms) {
528	        Person person = people.findByIdAndSheetId(id, sheetId)
529	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
530	        return update(sheetId, user, id, version, name, grade, gradeFrom, terms, person.getContact());
531	    }
532	
533	    /**
534	     * Edit a person as {@link #update(String, String, long, long, String, String, LocalDate, Integer)} does, their
535	     * contact becoming {@code contact} (stored trimmed and lower-cased; blank or null: none): refused when another
536	     * person on the sheet has it.
537	     */
538	    @Transactional
539	    public Person update(String sheetId, String user, long id, long version, String name, String grade,
540	            LocalDate gradeFrom, Integer terms, String contact) {
541	        LocalDate today = sheets.load(sheetId, user).getToday();
542	        Person person = people.findByIdAndSheetId(id, sheetId)
543	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
544	        if (person.getVersion() != version) {
545	            throw changedSince();
546	        }
547	        String trimmed = name.trim();
548	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, id)
549	                || people.findBySheetIdAndAliasIgnoreCase(sheetId, trimmed).isPresent()) {
550	            throw nameInUse();
551	        }
552	        String reach = contactOf(contact);
553	        if (reach != null && people.existsBySheetIdAndContactAndIdNot(sheetId, reach, id)) {
554	            throw contactInUse();
555	        }
556	        Rollup.Figures before = rollup.of(sheetId);
557	        person.setName(trimmed);
558	        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
559	            person.setGradeFrom(gradeFrom != null ? gradeFrom : today, grade);
560	        }
561	        boolean termsChanged = !Objects.equals(person.getTerms(), terms);
562	        person.setTerms(terms);
563	        boolean contactChanged = !Objects.equals(person.getContact(), reach);
564	        person.setContact(reach);
565	        Person edited = save(person);
566	        audit.recordChangeOnCommit(sheetId, user, entry("PERSON_EDITED", user, edited, edited.gradeOn(today))
567	                + (termsChanged ? " terms=" + (terms != null ? terms : "") : "")
568	                + (contactChanged ? " contact=" + (reach != null ? reach : "") : ""));
569	        rollup.recordChanges(sheetId, user, before);
570	        return edited;
571	    }
572	
573	    /** Retire a person from a date; a missing date takes the sheet's today. They count as retired at once; the live
574	     *  totals move with it once the sheet's today reaches the date. */
575	    @Transactional
576	    public Person retire(String sheetId, String user, long id, LocalDate from) {
577	        LocalDate today = sheets.load(sheetId, user).getToday();
578	        Person person = people.findByIdAndSheetId(id, sheetId)
579	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
580	        Rollup.Figures before = rollup.of(sheetId);
581	        person.setRetiredFrom(from != null ? from : today);
582	        Person retired = save(person);
583	        audit.recordChangeOnCommit(sheetId, user, "PERSON_RETIRED sheet=" + sheetId + " by=" + user
584	                + " name=" + retired.getName() + " from=" + retired.getRetiredFrom());
585	        rollup.recordChanges(sheetId, user, before);
586	        return retired;
587	    }
588	
589	    /** Put the person on hold from {@code from} (null: the sheet's today) to {@code to} (null: no end), alongside
590	     *  any holds they have already; the live totals move with it. A to-date before the from-date is refused. */
591	    @Transactional
592	    public Person hold(String sheetId, String user, long id, LocalDate from, LocalDate to) {
593	        LocalDate today = sheets.load(sheetId, user).getToday();
594	        Person person = people.findByIdAndSheetId(id, sheetId)
595	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
596	        LocalDate start = from != null ? from : today;
597	        if (to != null && to.isBefore(start)) {
598	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts");
599	        }
600	        Rollup.Figures before = rollup.of(sheetId);
601	        person.addHold(new Hold(start, to));
602	        Person saved = save(person);
603	        audit.recordChangeOnCommit(sheetId, user, "PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
604	                + " from=" + start);
605	        rollup.recordChanges(sheetId, user, before);
606	        return saved;
607	    }
608	
609	    /** Give the person an alias, stored trimmed: refused when blank, or when it is, without regard to case, any
610	     *  name or alias on the sheet. */
611	    @Transactional
612	    public Person addAlias(String sheetId, String user, long id, String alias) {
613	        sheets.load(sheetId, user);
614	        Person person = people.findByIdAndSheetId(id, sheetId)
615	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
616	        String trimmed = alias == null ? "" : alias.trim();
617	        if (trimmed.isEmpty()) {
618	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "An alias cannot be blank");
619	        }
620	        if (people.findBySheetIdAndNameOrAliasIgnoreCase(sheetId, trimmed).isPresent()) {
621	            throw nameInUse();
622	        }
623	        person.addAlias(trimmed);
624	        Person saved = save(person);
625	        audit.recordChangeOnCommit(sheetId, user, "PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user
626	                + " name=" + saved.getName() + " alias=" + trimmed);
627	        return saved;
628	    }
629	
630	    private static String entry(String event, String user, Person person, String grade) {
631	        return event + " sheet=" + person.getSheetId() + " by=" + user
632	                + " name=" + person.getName() + " grade=" + grade;
633	    }
634	
635	    private Person save(Person person) {
636	        try {
637	            return people.saveAndFlush(person);
638	        } catch (DataIntegrityViolationException raced) {
639	            // Another user took the same name at the same moment: theirs stands.
640	            throw nameInUse();
641	        } catch (ObjectOptimisticLockingFailureException raced) {
642	            // Another user saved the same person at the same moment: theirs stands.
643	            throw changedSince();
644	        }
645	    }
646	
647	    private static ResponseStatusException changedSince() {
648	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
649	                "Someone else has saved this person since it was opened");
650	    }
651	
652	    /** A contact as stored: trimmed and lower-cased; null when blank or not given. */
653	    private static String contactOf(String contact) {
654	        if (contact == null || contact.isBlank()) {
655	            return null;
656	        }
657	        return contact.trim().toLowerCase(Locale.ROOT);
658	    }
659	
660	    private static ResponseStatusException contactInUse() {
661	        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on this sheet");
662	    }
663	
664	    private static ResponseStatusException nameInUse() {
665	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet");
666	    }
667	}
668	package net.officefloor.hq.app.person;
669	
670	import java.util.ArrayList;
671	import java.util.Comparator;
672	import java.util.LinkedHashSet;
673	import java.util.List;
674	import java.util.Set;
675	import net.officefloor.hq.app.Audit;
676	import net.officefloor.hq.app.claim.Claim;
677	import net.officefloor.hq.app.claim.ClaimRepository;
678	import net.officefloor.hq.app.patron.Patron;
679	import net.officefloor.hq.app.patron.PatronRepository;
680	import net.officefloor.hq.app.pool.PoolMember;
681	import net.officefloor.hq.app.pool.PoolMemberRepository;
682	import net.officefloor.hq.app.role.Role;
683	import net.officefloor.hq.app.role.RoleService;
684	import net.officefloor.hq.app.rollup.Rollup;
685	import net.officefloor.hq.app.sheet.SheetRepository;
686	import net.officefloor.hq.app.sheet.SheetService;
687	import net.officefloor.hq.app.statement.StatementRepository;
688	import net.officefloor.hq.app.watch.WatchRepository;
689	import org.springframework.http.HttpStatus;
690	import org.springframework.stereotype.Service;
691	import org.springframework.transaction.annotation.Transactional;
692	import org.springframework.web.server.ResponseStatusException;
693	
694	/** Merging one person of a sheet into another. */
695	@Service
696	public class PersonMergeService {
697	
698	    private final PersonRepository people;
699	    private final ClaimRepository claims;
700	    private final PatronRepository patrons;
701	    private final PoolMemberRepository poolMembers;
702	    private final StatementRepository statements;
703	    private final WatchRepository watches;
704	    private final SheetService sheets;
705	    private final SheetRepository sheetStore;
706	    private final RoleService roles;
707	    private final Audit audit;
708	    private final Rollup rollup;
709	
710	    public PersonMergeService(PersonRepository people, ClaimRepository claims, PatronRepository patrons,
711	            PoolMemberRepository poolMembers, StatementRepository statements, WatchRepository watches,
712	            SheetService sheets, SheetRepository sheetStore, RoleService roles, Audit audit, Rollup rollup) {
713	        this.people = people;
714	        this.claims = claims;
715	        this.patrons = patrons;
716	        this.poolMembers = poolMembers;
717	        this.statements = statements;
718	        this.watches = watches;
719	        this.sheets = sheets;
720	        this.sheetStore = sheetStore;
721	        this.roles = roles;
722	        this.audit = audit;
723	        this.rollup = rollup;
724	    }
725	
726	    /**
727	     * A steward merges a person into another of the sheet. The merged person's claims move to the other, keeping
728	     * their numbers and dates, listed as the other's newest in the order they were added, each losing any figure a
729	     * statement bound it to; their name and aliases become aliases of the other; their patrons are added to the
730	     * other's (never the other themselves, nor one twice), anyone naming them as patron names the other instead (once),
731	     * and their pool memberships move to the other (shares added where the other is already a member). Their
732	     * statements, holds, watchers and contact are dropped with them. Refused for anyone but a steward, a merge into
733	     * the same person, and when either of them is retired.
734	     */
735	    @Transactional
736	    public Person merge(String sheetId, String user, long id, long intoId) {
737	        sheets.load(sheetId, user);
738	        sheetStore.findLockedById(sheetId).orElseThrow();
739	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
740	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can merge people");
741	        }
742	        Person from = people.findByIdAndSheetId(id, sheetId)
743	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
744	        Person into = people.findByIdAndSheetId(intoId, sheetId)
745	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
746	        if (from.getId().equals(into.getId())) {
747	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be merged into themselves");
748	        }
749	        if (from.isRetired() || into.isRetired()) {
750	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged");
751	        }
752	        Rollup.Figures before = rollup.of(sheetId);
753	
754	        long listed = claims.lastListed(sheetId);
755	        List<Claim> moving = claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, from.getId()).stream()
756	                .sorted(Comparator.comparing(Claim::getId)).toList();
757	        for (Claim claim : moving) {
758	            claim.unbind();
759	            claim.reassign(into.getId(), ++listed);
760	        }
761	        claims.saveAll(moving);
762	
763	        // The patron pairs the other has once the merged person's are taken over.
764	        List<Patron> sheetPatrons = patrons.findBySheetIdOrderByIdAsc(sheetId);
765	        Set<List<Long>> pairs = new LinkedHashSet<>();
766	        sheetPatrons.stream().filter(p -> !p.getPersonId().equals(from.getId()) && !p.getPatronId().equals(from.getId()))
767	                .forEach(p -> pairs.add(List.of(p.getPersonId(), p.getPatronId())));
768	        List<Patron> gone = new ArrayList<>();
769	        List<Patron> added = new ArrayList<>();
770	        for (Patron p : sheetPatrons) {
771	            if (!p.getPersonId().equals(from.getId()) && !p.getPatronId().equals(from.getId())) {
772	                continue;
773	            }
774	            gone.add(p);
775	            long person = p.getPersonId().equals(from.getId()) ? into.getId() : p.getPersonId();
776	            long patron = p.getPatronId().equals(from.getId()) ? into.getId() : p.getPatronId();
777	            if (person != patron && pairs.add(List.of(person, patron))) {
778	                added.add(new Patron(sheetId, person, patron));
779	            }
780	        }
781	        patrons.deleteAll(gone);
782	        patrons.flush();
783	
784	        for (PoolMember member : poolMembers.findByPersonIdOrderByIdAsc(from.getId())) {
785	            var existing = poolMembers.findByPoolIdAndPersonId(member.getPoolId(), into.getId());
786	            if (existing.isPresent()) {
787	                existing.get().setShare(existing.get().getShare().add(member.getShare()));
788	                poolMembers.delete(member);
789	            } else {
790	                member.moveTo(into.getId());
791	            }
792	        }
793	        poolMembers.flush();
794	
795	        statements.deleteAll(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, from.getId()));
796	        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
797	        String fromName = from.getName();
798	        List<String> fromAliases = from.getAliases();
799	        people.delete(from);
800	        people.flush();
801	
802	        patrons.saveAll(added);
803	        into.addAlias(fromName);
804	        fromAliases.forEach(into::addAlias);
805	        Person merged = people.saveAndFlush(into);
806	        audit.recordChangeOnCommit(sheetId, user, "PERSON_MERGED sheet=" + sheetId + " by=" + user
807	                + " from=" + fromName + " into=" + merged.getName());
808	        rollup.recordChanges(sheetId, user, before);
809	        return merged;
810	    }
811	}
